// ============================================================
// CONFIG — fill in your API keys
// ============================================================
const ANTHROPIC_API_KEY = $env.ANTHROPIC_API_KEY;
const TODOIST_API_KEY   = $env.TODOIST_API_KEY;

// ============================================================
// Parse incoming Todoist webhook
// ============================================================
const body = $input.first().json;

// Only handle item:added events
if (body.event_name !== 'item:added') {
  return [{ json: { skipped: true, reason: 'not item:added' } }];
}

const task = body.event_data;
const taskId      = task.id;
const title       = task.content || '';
const description = task.description || '';
const hasLabels   = Array.isArray(task.labels) && task.labels.length > 0;
const hasDue      = task.due !== null && task.due !== undefined;

// If already has labels AND due date — do nothing
if (hasLabels && hasDue) {
  return [{ json: { skipped: true, reason: 'already has labels and due date' } }];
}

// ============================================================
// SYSTEM PROMPT — full label catalog
// ============================================================
const SYSTEM_PROMPT = `You are a task labeler for a personal productivity system.
Given a task title and description (may be in Hebrew, English, or mixed language), analyze the task's intent and assign relevant labels.

Return ONLY a valid JSON object with no additional text. Format:
{
  "labels": ["LabelName", ...],
  "reasoning": "Brief explanation",
  "confidence": { "LabelName": 85, ... }
}

Rules:
- A task can have multiple labels
- Only include labels in "labels" that you are 60% or more confident about
- If NO labels reach 60% confidence, return an empty "labels" array
- Never include "Reception" in your response — that is handled by the caller
- Analyze intent, not just keywords
- Include ALL considered labels in the "confidence" object (even below 60%)

Available labels:

**Redeemable** — Accumulated value/entitlements to use before lost: points, credits, coupons, gift cards, loyalty rewards, cashback, miles, free trials, membership benefits, grants, mentorship programs.
Examples: "Check remaining 10,000-credit balance on Amazon", "Redeem CARLA CASH of $480", "$100 Coupon Duty Free", "Contact the Ogen Foundation to get business mentoring"

**Day Routines** — Recurring habits during waking hours. Daily rituals, health habits, supplements, exercise, hydration, spiritual practices.
Examples: "להניח תפילין בהודיה", "15Min Meditation", "15-Min Writing Session", "Call סבתוש"

**Night Routines** — Evening and bedtime habits. Wind-down rituals, sleep prep, pills, relaxation, next-day preparation.
Examples: "Pills", "PRACTICE ENGLISH GRAMMER!", "15Min Meditation"

**OnCauch** — Low-energy tasks for relaxed states. Things from your phone, passive consumption, ordering online, browsing. No focus required.
Examples: "Check The Whole Cloud", "להזמין תחפושת לפורים מעלי", "למצוא בית להתארח בו לנוביגוד"

**NoComp** — Tasks away from the computer. Physical errands, phone calls, outside activities, real-world actions, offline.
Examples: "Print the families physical photo albums", "לחדש מרשם לבדיקת שומן לבבי", "IG Cleaning - Unfollowing MF"

**10X** — High-impact tasks with significant results. Strategic, business-critical, life-changing, high leverage.
Examples: "לבנות מנוע חיפוש AI לערוץ יוטיוב", "לעשות שינויי מיינדסט על כסף - cashflow"

**ToBuy** — Anything to purchase or order. Physical items, digital products, services, gifts. Shopping intent in any language.
Examples: "לקנות מרץ של 2פאק", "לקנות PIGGY BANK", "buy chucky shit", "לקנות crest להלבנת שיניים", "Buy razor rojo"

**Neveloth** — Not important, not urgent, annoying tasks you keep postponing. Low motivation, easy to procrastinate, administrative nuisances.
Examples: "לסדרר את הקודים של המזוודה", "לעשות גיבוי לווצאפ", "לעשות TSA PreCheck", "Fix add-ons bar on system gmail"

**Bookkeeping** — Financial administration. Invoices, receipts, expenses, taxes, payments, refunds, bank transfers, subscriptions, domain renewals, debts.
Examples: "2-Month Bookkeeping", "להעביר 5000 לONEZERO", "פול חובה 1050 שח", "Handle the refund from Katamind"

**Car** — Tasks while driving or from car. Audio/video content, podcasts, phone calls while driving, picking something up on the way.
Examples: "לראות את הקורס היי וייב קומיוניקיישן של טיילר", "לדבר עם שיר צילומים מערק", "Call סבתוש"

**Creative** — Generative and creative work. Design, writing, brainstorming, content creation, copywriting, ideation, strategy.
Examples: "להכין פוסטים למערק", "לכתוב קופי לזריקות החדשות באפוס", "write liats whatsapp massages copy"

**Followup** — Waiting on something or someone. Need to chase, check status, ping again, await response, verify something happened.
Examples: "לראות שקיבלנו את הכסף חזרה מנפש אחת", "FOLLOWUP MODANRIANS", "Checkup on Linoy progress"

**10min** — Quick tasks under 10 minutes. Easy wins, low effort, good for gaps between bigger work.
Examples: "להעביר 5000 לONEZERO", "לשכפל מפתח לחדר", "לחדש מרשם", "Reset Dating Apps"

**Brainless** — Zero thinking required. Mechanical, autopilot, mindless execution. Good when tired or multitasking.
Examples: "להעביר 5000 לONEZERO", "Check The Whole Cloud", "Print the families physical photo albums"

**Bottleneck** — Blocking other work. Must be done first to unlock progress. Critical path, others depend on this.
Examples: "לשכפל מפתח לחדר", "Print the families physical photo albums", "Reset Dating Apps"

**Flights** — Tasks for long flights with laptop. Deep work, learning, courses, research, writing.
Examples: "לשים התראות על הזדמנויות קנייה בשוק ההון ובקריפטו", "לעשות TSA PreCheck"

**Link** — Task contains or references a URL. Something to read, watch, review, sign up, fill out, or act on online.
Examples: Tasks containing URLs to watch, read, fill forms, or review

**FamilyMatters** — Family-related. Parents, siblings, grandparents, relatives, obligations, coordination, helping family, home maintenance.
Examples: "Checkup on Linoy progress + Send Her Content", "להחליף פילטר מים בבית", "לקחת את אמא לבילוי"

**Personal Optimization** — Self-improvement and life optimization. Productivity tools, health, fitness, habits, learning, skill-building, personal growth, dating optimization.
Examples: "CREATE INBOX ZERO FOR EMAIL", "להחליף סיסמאות חוזרות", "ללמוד מבטא אנגלית אמרקיאית", "optimize my internet profile pic"

**Assets** — Things you own that need attention. Investments, property, equipment, domains, accounts, digital assets.
Examples: "Presstor.com"

**ToAutomate** — Automation ideas to build. Future n8n workflows, agents, scripts, systems. Not now, but concepts to implement later.
Examples: "pic of an gym machine + its lbs > doc notion", "myMusic Automations"`;

// ============================================================
// Call Anthropic
// ============================================================
let labelsToApply = ['Reception'];
let reasoning = 'fallback to Reception';

if (!hasLabels) {
  const userMessage = [
    `Task title: ${title}`,
    description ? `Task description: ${description}` : null,
    '',
    'Analyze this task and return your label assessment as JSON.',
  ].filter(Boolean).join('\n');

  const anthropicRes = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'x-api-key': ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 800,
      system: SYSTEM_PROMPT,
      messages: [{ role: 'user', content: userMessage }],
    }),
  });

  if (!anthropicRes.ok) {
    throw new Error(`Anthropic API error ${anthropicRes.status}: ${await anthropicRes.text()}`);
  }

  const anthropicData = await anthropicRes.json();
  const raw = anthropicData.content[0].text.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  const analysis = JSON.parse(raw);
  const qualified = (analysis.labels || []).filter(
    (label) => (analysis.confidence?.[label] ?? 0) >= 60
  );

  labelsToApply = qualified.length > 0 ? qualified : ['Reception'];
  reasoning = analysis.reasoning || '';
}

// ============================================================
// Update task in Todoist
// ============================================================
const updateBody = {};

if (!hasLabels) {
  updateBody.labels = labelsToApply;
}
if (!hasDue) {
  updateBody.due_string = 'today';
}

if (Object.keys(updateBody).length > 0) {
  const todoistRes = await fetch(`https://api.todoist.com/rest/v2/tasks/${taskId}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${TODOIST_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(updateBody),
  });

  if (!todoistRes.ok) {
    throw new Error(`Todoist API error ${todoistRes.status}: ${await todoistRes.text()}`);
  }
}

return [{
  json: {
    taskId,
    title,
    labelsApplied: updateBody.labels ?? 'skipped (already had labels)',
    dueDateSet: updateBody.due_string ?? 'skipped (already had due date)',
    reasoning,
  }
}];
